def inr_format(n):
    if n <= 3:
        return str(n)
    parts = []
    # Extract last 3 digits
    last_three = str(n)[-3:]
    parts.append(last_three)
    # Extract groups of 2 digits
    while len(parts) > 2:
        parts.insert(0, parts[-2:])
        parts.pop()
    return ','.join(parts) + ',' + last_three

